@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
  + inhabitants : User[]
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : string
  + room : Room
}

class TemperatureSensor {
  + minValue : double
  + maxValue : double
}

class PowerSensor {}

class Room {
  + description : string
}

class Value {
  + timestamp : datetime
  + value : float
}

class User {
  + username : string
  + password : string
  + isAdmin : boolean
}

class EMonitor {
  // External system to check thresholds and send alerts
}

SensorController "1" -- "*" Apartment
Apartment "0..*" -- "* inhabitants" User
User "1" -- "*" Sensor
Room "1" -- "*" Sensor
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
Sensor "0..*" -- "*" Value
EMonitor ..|> SensorController

@enduml

